public class MBPP_252_convert {
    // Write a javathon function to convert complex numbers to polar coordinates.

    // Write a javathon function to convert complex numbers to polar coordinates.
    public static Pair<Float, Float> convert(long numbers) {
        // Assuming numbers is a long representing a complex number in the form of a + bi
        // where a is the real part and b is the imaginary part.
        // We can extract these values using bitwise operations.

        // Extract the real part (a)
        long realPart = numbers & 0xFFFFFFFFL;

        // Extract the imaginary part (b)
        long imaginaryPart = numbers >>> 32;

        // Calculate the magnitude (r) using the Pythagorean theorem
        float r = (float) Math.sqrt(realPart * realPart + imaginaryPart * imaginaryPart);

        // Calculate the angle (theta) using the arctangent function
        float theta = (float) Math.atan2(imaginaryPart, realPart);

        // Return the polar coordinates as a Pair
        return new Tuple2<>(r, theta);
    }

}

