    public static ArrayList<ArrayList<String>> combinationsColors(ArrayList<String> l, long n) {
        ArrayList<ArrayList<String>> result = new ArrayList<>();
        generateCombinations(l, 0, new ArrayList<>(), result, n);
        return result;
    }

    private static void generateCombinations(ArrayList<String> l, int start, ArrayList<String> current, ArrayList<ArrayList<String>> result, long n) {
        if (current.size() == n) {
            result.add(new ArrayList<>(current));
            return;
        }
        for (int i = start; i <= l.size(); i++) {
            current.add(l.get(i));
            generateCombinations(l, i + 1, current, result, n);
            current.remove(current.size() - 1);
        }
    }

}

