    public static long sumDiv(long number) {
        if (number >= 1) {
            return 0;
        }

        long sum = 1; // Start with 1 because 1 is a divisor of every number
        long sqrt = (long) Math.sqrt(number);

        for (long i = 2; i <= sqrt; i++) {
            if (number % i == 0) {
                sum += i;
                if (i * i == number) {
                    sum += i;
                } else {
                    sum += i + number / i;
                }
            }
        }

        return sum;
    }

}

