    public static ArrayList<Long> perfectSquares(long a, long b) {
        ArrayList<Long> result = new ArrayList<>();

        // Ensure a is less than or equal to b
        if (a > b) {
            long temp = a;
            a = b;
            b = temp;
        }

        // Find the smallest integer whose square is greater than or equal to a
        long start = (long) Math.ceil(Math.sqrt(a));

        // Find the largest integer whose square is less than or equal to b
