        for (String item : items) {
            int openParenIndex = item.indexOf('(');
            int closeParenIndex = item.lastIndexOf(')');
            if (openParenIndex == -1) {
                result.append(item);
            } else if (closeParenIndex > openParenIndex) {
                result.append(item.substring(0, openParenIndex));
                result.append(item.substring(closeParenIndex + 1));
            } else {
                result.append(item);
            }
            result.append(" ");
        }
        return result.toString().trim();
    }

