public class MBPP_747_lcs_of_three {
    // Write a function to find the longest common subsequence for the given three string sequence. https://www.geeksforgeeks.org/lcs-longest-common-subsequence-three-strings/

    // Write a function to find the longest common subsequence for the given three string sequence. https://www.geeksforgeeks.org/lcs-longest-common-subsequence-three-strings/
    public static long lcsOfThree(String X, String Y, String Z) {
        int m = X.length();
        int n = Y.length();
        int o = Z.length();

        // Create a 3D array to store lengths of longest common subsequence
        long[][][] dp = new long[m + 1][n + 1][o + 1];

        // Build the dp array from bottom up
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                for (int k = 1; k <= o; k++) {
                    if (X.charAt(i - 1) == Y.charAt(j - 1) && Y.charAt(j - 1) == Z.charAt(k - 1)) {
                        dp[i][j][k] = dp[i - 1][j - 1][k - 1] + 1;
                    } else {
                        dp[i][j][k] = Math.max(Math.max(dp[i - 1][j][k], dp[i][j - 1][k]), dp[i][j][k - 1]);
                    }
                }
            }
        }

        // The length of the longest common subsequence of X, Y, and Z
        return dp[m][n][o];
    }

}

